import assert from 'node:assert/strict';
import { createWorkspace } from './src/workspace.js';
import { createDraftStore } from './src/draft-store.js';
import { createReceiptArchive } from './src/receipt-archive.js';
function setup(onSaved = () => {}) {
  const callbacks = new Map(); let next = 0;
  const timers = { schedule(fn, delay) { assert.equal(delay, 120); const id = ++next; callbacks.set(id, fn); return id; }, cancel(id) { callbacks.delete(id); } };
  const store = createDraftStore(); const archive = createReceiptArchive();
  const documents = [], statuses = [], submissions = [];
  const workspace = createWorkspace({ store, archive, timers, onSaved, renderDocument: x => documents.push(x), renderStatus: x => statuses.push(x), renderSubmission: x => submissions.push(x) });
  return { callbacks, store, archive, documents, statuses, submissions, workspace, run() { const [id, fn] = callbacks.entries().next().value; callbacks.delete(id); fn(); } };
}
{
  const x = setup(); x.workspace.open('a'); x.workspace.edit('1'); x.workspace.edit('2'); assert.equal(x.store.read('a'), ''); assert.equal(x.callbacks.size, 1); x.run(); assert.equal(x.store.read('a'), '2'); x.workspace.edit('3'); x.run(); assert.equal(x.store.read('a'), '3'); x.workspace.edit('4'); x.workspace.close(); assert.equal(x.store.read('a'), '4'); assert.equal(x.statuses.at(-1).text, '3'); assert.equal(x.callbacks.size, 0);
}
{
  const x = setup(); x.workspace.open('a'); x.workspace.edit('draft'); const receipt = x.workspace.submit(); assert.deepEqual(receipt, {id:'a',text:'draft'}); assert.equal(x.store.read('a'), 'draft'); assert.equal(x.submissions.at(-1), receipt);
}
{
  const x = setup((event, nav) => { if (event.text === 'old') nav.open('b'); }); x.workspace.open('a'); x.workspace.edit('old'); x.workspace.open('c'); assert.equal(x.store.read('a'), 'old'); assert.equal(x.documents.at(-1).id, 'b');
}
{
  const x = setup((event, nav) => { if (event.text === 'first') nav.edit('second'); }); x.workspace.open('a'); x.workspace.edit('first'); x.run(); assert.equal(x.store.read('a'), 'first'); assert.equal(x.callbacks.size, 1); x.run(); assert.equal(x.store.read('a'), 'second');
}
{
  const x = setup((event, nav) => { if (event.text === 'draft') nav.open('b'); }); x.workspace.open('a'); x.workspace.edit('draft'); const receipt = x.workspace.submit(); assert.deepEqual(receipt, {id:'a',text:'draft'}); assert.equal(x.submissions.at(-1), null); assert.equal(x.documents.at(-1).id, 'b');
}
console.log('editor lifecycle checks passed');
EOF"

